function armsLoadout(k) {
  if (ARMS_HERO_MODE && S.hero && k === 'me') {
    const a=S.hero.autoSpec15,level=hLevel(k);
    if (a && a.version===1 && a.chosen===null && Number.isFinite(a.roll) && a.roll>=0 && a.roll<1 && Number.isInteger(level) && level>=1 && level<15) return {neutralTraining:true};
  }

function neutralTrainingText(id,text) {
  return id === 'heroicstrike' ? 'Отдельный удар после автоатаки: 100% атаки, повышенная угроза. Требует 15 ярости; учебный ИИ не резервирует ярость на Удар щитом.' : text;
}
function neutralTrainingSkillsHtml(cls,level) {
  const auto=B.autoOf(cls,null);
  const items=B.neutralTraining.slots(cls,level).map(function(slot){
    const d=B.SKILLS[slot.id],cost=d.rage!==undefined?'ярость '+B.rageCostText(slot.id):d.energy!==undefined?'энергия '+d.energy:d.mana?'мана '+d.mana:'без затрат ресурса';
    return '<li data-neutral-skill="'+esc(slot.id)+'" data-available="'+slot.available+'" data-own-level="'+level+'"'+(slot.available?'':' class="az-ability-locked"')+'>'+wowIcon(d)+' <b>'+esc(slot.name)+'</b> · '+esc(slot.available?'с '+slot.unlockLevel+' ур.':'Откроется на '+slot.unlockLevel+' уровне')+' · '+esc(cost)+' · перезарядка '+d.cd+'<br>'+esc(neutralTrainingText(slot.id,slot.description))+'</li>';
  }).join('');
  return '<details class="sk" open data-neutral-training="'+esc(cls)+'" data-own-level="'+level+'"><summary>Учебный набор · '+esc(B.CLASSES[cls].name)+'</summary><p>Автоатака: '+esc(auto.name)+'. До 15 уровня специализация не назначена; её аура и пассивки не действуют. На 1 уровне доступна автоатака.</p><ul>'+items+'</ul></details>';
}
function armsHeroPanel() {
  if (armsLoadout('me').neutralTraining === true) return neutralTrainingSkillsHtml(S.main,hLevel('me'));

const k = inf.dataset.info, ck = clsOf(k), c = B.CLASSES[ck], training=armsLoadout(k).neutralTraining===true, view=training?kStats(k):null;
const sp=training?{name:'Учебный набор',role:'training',armor:view.unit.armor,res:view.unit.res,spd:view.unit.spd}:B.specOf(ck,specKey(k));
const hs=training?view:B.heroStats(ck,specKey(k),hLevel(k)), lg=document.querySelector('#prep details.legend');
